
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:2}).format(v);const date=v=>v?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Fortaleza'}).format(new Date(v.includes('T')?v:v+'T12:00:00Z')):'—';const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const paths={search:'<circle cx="10.8" cy="10.8" r="6.7"/><path d="m16 16 4.5 4.5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',arrowup:'<path d="M6 18 18 6M6 6h12v12"/>',heart:'<path d="M20.7 4.6a5.5 5.5 0 0 0-7.8 0l-.9.9-.9-.9a5.5 5.5 0 0 0-7.8 7.8L12 21l8.7-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',star:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.4 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9Z"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-8Z"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v5m-2.5-2.5h5M4 18v4m-2-2h4"/>',drop:'<path d="M12 2C8 7 5 10 5 14a7 7 0 0 0 14 0c0-4-3-7-7-12Z"/><path d="M8 14a4 4 0 0 0 4 4"/>',paint:'<rect x="3" y="3" width="14" height="6" rx="2"/><path d="M17 5h3v7h-8v3m-2 0h4v7h-4Z"/>',snow:'<path d="M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M9 4l3 3 3-3M9 20l3-3 3 3M3 10l4-1-1-4M18 19l-1-4 4-1M3 14l4 1-1 4M18 5l-1 4 4 1"/>',chair:'<path d="M6 12V4a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v8M4 11h3v5h10v-5h3v9H4ZM6 20v2m12-2v2"/>',tools:'<path d="m14 6-8 8m-2 4 2 2 14-14-2-2ZM4 3l4 1 2 4-3 3-4-2-1-4m12 9 6 6-2 2-6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 3a4 4 0 0 1 0 8m3 10v-2a7 7 0 0 0-3-5"/>',shield:'<path d="m12 2 8 3v6c0 5-8 11-8 11S4 16 4 11V5Z"/><path d="m8 12 3 3 5-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chevron:'<path d="m8 10 4 4 4-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l1.8-5A9 9 0 1 1 21 11Z"/><path d="M7 10h10m-10 4h6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15ZM12 3H4v18h16v-8"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',plus:'<path d="M12 5v14M5 12h14"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v5h5M8 12h8m-8 4h8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12a20 20 0 0 0 18 0M10 13h4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',logout:'<path d="M10 3H4v18h6m4-14 5 5-5 5m-6-5h13"/>',leaf:'<path d="M20 3C4 1 1 13 8 17s14-1 12-14ZM5 21 16 8"/>'};
const icon=(name,size=20,fill=false)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="${fill?'currentColor':'none'}" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.tools}</svg>`;
const logo=()=>`<a class="brand" href="#inicio" aria-label="Conectta Serra — início"><span class="brand-mark"><svg width="38" height="38" viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M23 9a12 12 0 1 0 0 22M17 9a12 12 0 1 1 0 22" stroke="currentColor" stroke-width="5.3"/></svg></span><span><span class="brand-name">conectta<span style="color:var(--red)">.</span></span><span class="brand-label">SERRA TALHADA</span></span></a>`;
const palettes=[['#e9dec5','#8c7244'],['#dce6dd','#6a8972'],['#e0e5eb','#728095'],['#edcfc6','#b57462'],['#d8e7e7','#5f8c90'],['#eadccf','#967457']];
let state={user:null,categories:[],services:[],requests:[],favorites:[],csrf:'',filter:{q:'',category:'',neighborhood:'',sort:''},requestFilter:'todas',adminTab:'usuarios',manage:null,report:{status:'',from:'',to:''}};let toastTimer;
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':state.csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'Não foi possível conectar. Tente novamente.')}return r.json()}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4500)}
async function sync(){Object.assign(state,await api('/api/bootstrap'))}
function openModal(title,subtitle,content){$('#modal-body').innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Fechar janela">${icon('close',18)}</button></div><div class="modal-content">${content}</div>`;if(!$('#modal').open)$('#modal').showModal()}
const errorBox=()=>'<div class="form-error" role="alert"></div>';
const actions=(label='Salvar')=>`<div class="modal-actions"><button type="button" class="btn outline" data-action="close">Cancelar</button><button class="btn primary" type="submit">${label} ${icon('arrow',16)}</button></div>`;
const field=(label,name,value='',type='text',full=false,extra='')=>`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const selectField=(label,name,options,value='',full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}" required>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const area=(label,name,value='',min=10)=>`<label class="field full">${label}<textarea name="${name}" minlength="${min}" maxlength="1500" required>${esc(value)}</textarea></label>`;
function header(){const u=state.user;$('#header').innerHTML=`<div class="container header-inner">${logo()}<span class="location">${icon('pin',15)} Serra Talhada, PE ${icon('chevron',12)}</span><nav aria-label="Navegação principal"><a href="#explorar" class="${route()==='explorar'?'active':''}">Encontrar profissionais</a><a href="#como-funciona">Como funciona</a><a href="#solicitacoes" class="${route()==='solicitacoes'?'active':''}">Solicitações</a>${u&&u.role!=='cliente'?`<a href="#painel" class="${route()==='painel'?'active':''}">${u.role==='admin'?'Gestão':'Meu espaço'}</a>`:''}</nav><div class="head-actions">${!u?'<a class="text-btn signup-header-link" href="#cadastro-usuario">Cadastre-se</a>':''}<a href="#favoritos" class="icon-btn" aria-label="Meus favoritos">${icon('heart',19)}</a><button class="btn ${u?'outline':'primary'}" data-action="login">${u?`${icon('user',15)} ${esc(u.name.split(' ')[0])}`:`Entrar ${icon('arrowup',15)}`}</button><button class="icon-btn menu-btn" data-action="menu" aria-label="Abrir menu" aria-expanded="false">${icon('menu',22)}</button></div></div><div class="mobile-nav"><a href="#explorar">Encontrar profissionais</a><a href="#cadastro-usuario">Cadastro de usuário</a><a href="#cadastro-profissional">Cadastro de profissional</a><a href="#solicitacoes">Minhas solicitações</a><a href="#favoritos">Meus favoritos</a>${u&&u.role!=='cliente'?`<a href="#painel">${u.role==='admin'?'Gestão':'Meu espaço'}</a>`:''}<a href="#como-funciona">Como funciona</a></div>`}
function footer(){$('#footer').innerHTML=`<div class="container"><div class="footer-inner">${logo()}<p>O talento é daqui. A conexão também.<br>Feito para Serra Talhada, Pernambuco.</p><span>© 2026 Conectta Serra · <a href="#projeto" style="text-decoration:underline;text-underline-offset:3px">Sobre o projeto</a></span></div></div>`}
function scene(){return `<div class="hero-art"><span class="art-note">${icon('leaf',14)} Feito por gente da nossa terra</span><span class="floating-tag">${icon('pin',15)} Pertinho de você</span><svg class="scene" viewBox="0 0 500 400" fill="none" aria-label="Ilustração de uma casa, ferramentas e a paisagem do sertão" role="img"><path d="M44 316V200C44 79 122 44 245 44s205 78 205 198v74Z" fill="#F0E8D9"/><path d="m45 274 66-61 44 29 69-53 79 43 67-30 83 73" stroke="#D9CBB5" stroke-width="1.3"/><circle cx="354" cy="106" r="31" fill="#F2B544"/><path d="M24 330h452" stroke="#B9B2A3" stroke-width="1.3"/><path d="M142 189h214v141H142Z" fill="#EFB9A8"/><path d="m125 193 124-94 124 94" fill="#E47B61"/><path d="m117 191 132-101 133 101" stroke="#20232E" stroke-width="3" stroke-linejoin="round"/><path d="M248 99v228M143 196h212" stroke="#CE8E78" stroke-width="1.2"/><path d="M259 245c0-21 14-36 32-36s32 15 32 36v85h-64Z" fill="#F8EFDF"/><path d="M272 330v-83c0-14 8-24 19-24s19 10 19 24v83" stroke="#BFAF94" stroke-width="1.3"/><circle cx="302" cy="282" r="2" fill="#9C8C72"/><rect x="169" y="215" width="49" height="56" rx="22" fill="#FAF4E9"/><path d="M193 217v53m-24-23h49" stroke="#C8AE92" stroke-width="1.5"/><path d="M158 274h71" stroke="#C2816B" stroke-width="2"/><path d="M84 328v-68m0 20c-16 0-18-13-18-24v-14m18 24c18 0 20-14 20-29v-14" stroke="#76836A" stroke-width="11" stroke-linecap="round"/><path d="M412 328v-46m0 12c12-5 17-12 17-21m-17 25c-13 0-19-6-21-17" stroke="#8C987C" stroke-width="8" stroke-linecap="round"/><path d="M383 330h62l-8 29h-46Z" fill="#BD7960"/><path d="M378 330h71" stroke="#20232E" stroke-width="2"/><path d="M99 330h36v-56H99Z" fill="#20232E"/><path d="m98 277 11-27h18l9 27" fill="#F2B544"/><path d="M104 283h26m-26 11h26m-26 11h26" stroke="#5A5B60" stroke-width="1.5"/><g transform="translate(190 294) rotate(-15)"><rect x="-6" y="-18" width="57" height="45" rx="6" fill="#F2B544"/><path d="M9-18v-11h27v11M-6-3h57M20-7v9" stroke="#9B732E" stroke-width="2"/><path d="M8 9h29" stroke="#C68E2F" stroke-width="1.5"/></g><g transform="translate(363 162) rotate(20)"><rect x="-18" y="-36" width="63" height="89" rx="10" fill="#FAF9F6" stroke="#D9D1C4"/><path d="m17-12 4 16-8 8-16-4-16 25 7 5 19-23 14-1 9-13-1-14-9 12-8-3 1-8Z" fill="#AEB8BC" stroke="#708087" stroke-width="1.3"/></g><path d="m146 100 5-8m-15 6-2-9m7 85-11-3m270 126 11-5M376 69l4-8" stroke="#BD8B46" stroke-width="2" stroke-linecap="round"/><path d="M49 350h26m267 10h19m-260-7h17" stroke="#D5CDBF" stroke-width="1.4"/></svg><div class="floating-person"><span class="avatar">RL</span><div><strong>Rafael Lima</strong><small>Elétrica e reparos · Serra Talhada</small></div><span class="float-check">${icon('check',14)}</span></div><span class="scene-label">NOSSA TERRA. NOSSAS CONEXÕES.</span></div>`}
function rating(s){return `<span class="rating">${icon('star',12)} ${s.rating?Number(s.rating).toFixed(1).replace('.',','):'Novo'}${s.review_count?`<small>(${s.review_count})</small>`:''}</span>`}
function card(s){const p=palettes[(s.category_id-1)%palettes.length],saved=state.favorites.includes(s.professional_id);return `<article class="service-card"><div class="service-art" style="--art:${p[0]};--draw:${p[1]}"><span class="service-drawing">${icon(s.icon,104)}</span><button class="icon-btn ${saved?'saved':''}" data-action="favorite" data-id="${s.professional_id}" aria-label="${saved?'Remover dos':'Adicionar aos'} favoritos: ${esc(s.name)}" aria-pressed="${saved}">${icon('heart',16,saved)}</button><span class="category-badge">${esc(s.category)}</span></div><div class="card-body"><div class="provider"><span class="avatar">${esc(initials(s.name))}</span><span><strong>${esc(s.name)}</strong><small>${icon('pin',10)} ${esc(s.neighborhood)} · Serra Talhada</small></span>${rating(s)}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="card-bottom"><div><small>A partir de</small><strong>${money(s.price)} <span>/ ${esc(s.unit)}</span></strong></div><button class="text-btn" data-action="profile" data-id="${s.professional_id}">Ver perfil ${icon('arrowup',14)}</button></div></div></article>`}
function home(){return `<section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> CONEXÕES LOCAIS, POSSIBILIDADES REAIS</div><h1>Gente boa.<br><em>Serviço bem feito.</em></h1><p>Quem resolve o que você precisa pode estar bem pertinho. Encontre o talento de Serra Talhada.</p><form class="search-box" id="hero-search">${icon('search',20)}<input name="q" aria-label="Qual serviço você precisa?" placeholder="Qual serviço você precisa?" maxlength="100"><button class="btn primary" type="submit">Encontrar ${icon('arrow',16)}</button></form><div class="popular">Mais buscados: <button data-action="category" data-id="1">Eletricista</button><button data-action="category" data-id="2">Diarista</button><button data-action="category" data-id="3">Encanador</button></div><div class="hero-trust"><div class="mini-avatars"><span>RL</span><span>CS</span><span>JO</span></div><span><strong>${new Set(state.services.map(s=>s.professional_id)).size} profissionais</strong> na demonstração · talento 100% local</span></div></div>${scene()}</div></section><section class="categories-section"><div class="container"><div class="section-kicker">Um mundo de talentos, na sua cidade</div><div class="category-grid">${state.categories.slice(0,6).map(c=>`<button class="category" data-action="category" data-id="${c.id}">${icon(c.icon,23)} ${esc(c.name)}</button>`).join('')}</div></div></section><section class="featured"><div class="container"><div class="section-head"><div><div class="eyebrow" style="font-size:9px;margin-bottom:9px">TALENTOS DA NOSSA SERRA</div><h2>Encontre quem faz acontecer.</h2><p>Profissionais locais para deixar a sua rotina mais leve.</p></div><a class="text-btn" href="#explorar">Ver todos ${icon('arrowup',15)}</a></div><div class="cards">${state.services.slice(0,3).map(card).join('')||empty('Novas conexões estão chegando.','Cadastre o primeiro serviço no perfil profissional.')}</div></div></section>${how()}<section class="pro-cta"><div class="container"><div class="cta-inner"><div><div class="eyebrow">SEU TALENTO MERECE SER VISTO</div><h2>Você faz bem. A gente conecta.</h2><p>Mostre seu trabalho e encontre novos clientes em Serra Talhada.</p></div><button class="btn primary" data-action="register-pro">Quero ser um profissional ${icon('arrowup',16)}</button></div></div></section>`}
function how(){return `<section class="how" id="como-funciona"><div class="container how-head"><div><h2>Conectar é simples.<br>Resolver também.</h2><p>Da busca ao serviço concluído, tudo começa com uma boa conexão.</p></div><div class="steps"><div><span class="step-num">01 / ENCONTRE</span><h3>O talento certo para você</h3><p>Busque por serviço, categoria ou bairro. Conheça o perfil e as avaliações.</p></div><div><span class="step-num">02 / CONVERSE</span><h3>Combine os detalhes</h3><p>Peça um orçamento e converse com o profissional pela sua solicitação.</p></div><div><span class="step-num">03 / CONECTE</span><h3>Resolva e compartilhe</h3><p>Acompanhe o pedido e, depois de concluído, conte como foi sua experiência.</p></div></div></div></section>`}
function empty(title,description,button='Explorar serviços',action='explorar'){return `<div class="empty">${icon('search',35)}<h3>${esc(title)}</h3><p>${esc(description)}</p><a class="btn outline" href="#${action}">${esc(button)} ${icon('arrow',15)}</a></div>`}
function filteredServices(favorites=false){let ss=state.services;const f=state.filter;const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();ss=ss.filter(s=>(!favorites||state.favorites.includes(s.professional_id))&&(!f.q||norm(s.title+' '+s.name+' '+s.category+' '+s.profession+' '+s.description).includes(norm(f.q)))&&(!f.category||s.category_id===Number(f.category))&&(!f.neighborhood||s.neighborhood===f.neighborhood));if(f.sort==='price')ss.sort((a,b)=>a.price-b.price);if(f.sort==='rating')ss.sort((a,b)=>b.rating-a.rating);return ss}
function filters(){const f=state.filter;return `<form class="filters" id="filters"><label>O que você precisa?<input name="q" value="${esc(f.q)}" placeholder="Serviço ou profissional" maxlength="100"></label><label>Categoria<select name="category"><option value="">Todas as categorias</option>${state.categories.map(c=>`<option value="${c.id}" ${String(c.id)===String(f.category)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Bairro do profissional<select name="neighborhood"><option value="">Todos os bairros</option>${[...new Set(state.services.map(s=>s.neighborhood))].sort().map(n=>`<option ${f.neighborhood===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Ordenar por<select name="sort"><option value="">Relevância</option><option value="rating" ${f.sort==='rating'?'selected':''}>Melhor avaliação</option><option value="price" ${f.sort==='price'?'selected':''}>Menor preço inicial</option></select></label></form>`}
function catalog(favorites=false){if(favorites&&!state.user)return gated('Guarde suas boas conexões.','Entre em um perfil para salvar os profissionais que você gostou.');const ss=filteredServices(favorites);return `<div class="container page"><div class="breadcrumb"><a href="#inicio">Início</a> / ${favorites?'Favoritos':'Encontrar profissionais'}</div><div class="page-head"><div><div class="eyebrow"><span class="dot"></span> SERRA TALHADA, PE</div><h1>${favorites?'Suas melhores conexões.':'O que a sua rotina precisa?'}</h1><p>${favorites?'Seus profissionais favoritos, sempre por perto.':'Encontre gente da nossa cidade para fazer acontecer.'}</p></div></div>${filters()}<div class="result-count"><span><strong>${ss.length}</strong> ${ss.length===1?'serviço encontrado':'serviços encontrados'} · perfis de demonstração</span><button data-action="clear-filters">Limpar filtros</button></div><div class="cards" id="catalog-cards">${ss.map(card).join('')||empty(favorites?'Ainda não tem favoritos por aqui.':'Não encontramos essa conexão.','Experimente outra busca ou categoria para conhecer os profissionais.','Limpar busca','explorar')}</div></div>`}
function gated(title,desc){return `<div class="container page"><div class="empty">${icon('user',36)}<h1 style="font-size:30px">${title}</h1><p>${desc}</p><button class="btn primary" data-action="login">Experimentar um perfil ${icon('arrow',16)}</button></div></div>`}
const statusLabel={pendente:'Aguardando resposta',aceita:'Em andamento',concluida:'Concluída',cancelada:'Cancelada'};
function requestCard(r){const u=state.user;return `<article class="request-card"><div class="request-icon">${icon('briefcase',25)}</div><div class="request-info"><span class="badge ${r.status}">${statusLabel[r.status]} · #${r.id}</span><h3>${esc(r.title)}</h3><p>${u.role==='profissional'?'Cliente: '+esc(r.client_name):'Profissional: '+esc(r.professional_name)}</p><div class="meta"><span>${icon('calendar',12)} ${date(r.preferred_date)}</span><span>${icon('pin',12)} ${esc(r.neighborhood)}</span><span>Referência: ${money(r.price)}</span></div></div><div class="request-actions"><button class="btn outline small" data-action="chat" data-id="${r.id}">${icon('chat',14)} Detalhes e conversa</button>${r.status==='pendente'&&['profissional','admin'].includes(u.role)?`<button class="btn primary small" data-action="status" data-id="${r.id}" data-status="aceita">Aceitar</button>`:''}${r.status==='aceita'&&['cliente','admin'].includes(u.role)?`<button class="btn primary small" data-action="status" data-id="${r.id}" data-status="concluida">Concluir</button>`:''}${['pendente','aceita'].includes(r.status)&&['cliente','admin'].includes(u.role)?`<button class="text-btn" data-action="status" data-id="${r.id}" data-status="cancelada" aria-label="Cancelar solicitação ${r.id}">Cancelar</button>`:''}${r.status==='concluida'&&!r.review_id&&u.role==='cliente'?`<button class="btn subtle small" data-action="review" data-id="${r.id}">${icon('star',14)} Avaliar</button>`:''}</div></article>`}
function requestsPage(){if(!state.user)return gated('Cada pedido, uma nova conexão.','Entre para pedir um orçamento e acompanhar suas solicitações.');const f=state.requestFilter;const rr=state.requests.filter(r=>f==='todas'||r.status===f);return `<div class="container page"><div class="page-head"><div><div class="eyebrow"><span class="dot"></span> SUAS CONEXÕES</div><h1>${state.user.role==='profissional'?'Pedidos recebidos':'Minhas solicitações'}</h1><p>Combine os detalhes, acompanhe o serviço e converse por aqui.</p></div><a class="btn primary" href="#explorar">${icon('plus',16)} Novo pedido</a></div><div class="tabs">${[['todas','Todas'],['pendente','Pendentes'],['aceita','Em andamento'],['concluida','Concluídas'],['cancelada','Canceladas']].map(([v,l])=>`<button class="tab ${f===v?'active':''}" data-action="request-tab" data-id="${v}">${l}<span class="count">${state.requests.filter(r=>v==='todas'||r.status===v).length}</span></button>`).join('')}</div><div class="requests-list">${rr.map(requestCard).join('')||empty('Nenhuma solicitação por aqui.','Quando uma nova conexão acontecer, o pedido vai aparecer aqui.')}</div></div>`}
function stat(label,value,foot,ic){return `<div class="stat"><div class="stat-top">${label}${icon(ic,20)}</div><strong>${value}</strong><small>${foot}</small></div>`}
function rowActions(entity,id){if(entity==='users')return `<div class="row-actions user-row-actions"><button class="btn outline small" data-action="entity-view" data-entity="users" data-id="${id}" aria-label="Visualizar usuário ${id}">${icon('file',13)} Ver</button><button class="btn outline small" data-action="entity-edit" data-entity="users" data-id="${id}" aria-label="Editar usuário ${id}">${icon('edit',13)} Editar</button><button class="btn danger small" data-action="entity-delete" data-entity="users" data-id="${id}" aria-label="Excluir usuário ${id}">${icon('trash',13)} Excluir</button></div>`;return `<div class="row-actions"><button class="icon-btn" data-action="entity-view" data-entity="${entity}" data-id="${id}" aria-label="Visualizar ${entityNames[entity]} ${id}">${icon('file',14)}</button><button class="icon-btn" data-action="entity-edit" data-entity="${entity}" data-id="${id}" aria-label="Editar ${entityNames[entity]} ${id}">${icon('edit',14)}</button><button class="icon-btn" data-action="entity-delete" data-entity="${entity}" data-id="${id}" aria-label="Excluir ${entityNames[entity]} ${id}">${icon('trash',14)}</button></div>`}
let usersFilters={q:'',role:''};
const normalizeUserSearch=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function selectedUsers(){const q=normalizeUserSearch(usersFilters.q);return state.manage.users.filter(u=>(!usersFilters.role||u.role===usersFilters.role)&&(!q||normalizeUserSearch(u.name+' '+u.email+' '+u.neighborhood).includes(q)))}
function usersTableRows(){const users=selectedUsers();return users.length?users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td><span class="badge ${u.role}">${esc(u.role)}</span></td><td>${esc(u.neighborhood)}</td><td>${rowActions('users',u.id)}</td></tr>`).join(''):`<tr><td colspan="4"><div class="users-empty"><strong>Nenhum usuário encontrado.</strong><p>Experimente outro nome, e-mail, bairro ou perfil.</p></div></td></tr>`}
function updateUsersResults(){const rows=$('#searchable-rows');if(!rows)return;rows.innerHTML=usersTableRows();const count=$('#users-count');if(count)count.textContent=selectedUsers().length+' de '+state.manage.users.length+' usuários';}
function usersPanel(){return `<div class="panel"><div class="panel-head"><div><h2>Usuários da plataforma</h2><p>Cadastre, consulte, edite e exclua os usuários da demonstração.</p></div><button class="btn primary small" data-action="entity-new" data-entity="users">${icon('plus',15)} Novo usuário</button></div><div class="users-filter-bar"><label class="field">Buscar usuário<input id="table-search" value="${esc(usersFilters.q)}" placeholder="Nome, e-mail ou bairro" maxlength="120" aria-controls="searchable-rows"></label><label class="field">Perfil<select id="users-role-filter"><option value="">Todos os perfis</option>${[['cliente','Cliente'],['profissional','Profissional'],['admin','Administrador']].map(([v,l])=>`<option value="${v}" ${usersFilters.role===v?'selected':''}>${l}</option>`).join('')}</select></label><span id="users-count" class="subdued" role="status" aria-live="polite">${selectedUsers().length} de ${state.manage.users.length} usuários</span></div><div class="table-wrap"><table><thead><tr><th>Nome / e-mail</th><th>Perfil</th><th>Bairro</th><th>Ações</th></tr></thead><tbody id="searchable-rows">${usersTableRows()}</tbody></table></div></div>`}
function servicePanel(){const data=state.manage.services;return `<div class="panel"><div class="panel-head"><div><h2>${state.user.role==='admin'?'Serviços cadastrados':'O que você faz bem'}</h2><p>${data.length} serviços · preços de referência, orçamento a combinar.</p></div><button class="btn primary small" data-action="entity-new" data-entity="services">${icon('plus',15)} Novo serviço</button></div><div class="table-wrap"><table><thead><tr><th>Serviço</th><th>Categoria</th><th>A partir de</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${data.map(s=>`<tr><td><strong>${esc(s.title)}</strong><small>${esc(s.name)}</small></td><td>${esc(s.category)}</td><td>${money(s.price)}<small>/ ${esc(s.unit)}</small></td><td><span class="badge ${s.active?'concluida':'cancelada'}">${s.active?'Ativo':'Pausado'}</span></td><td>${rowActions('services',s.id)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum serviço. Cadastre seu primeiro talento.</td></tr>'}</tbody></table></div></div>`}
function categoryPanel(){return `<div class="panel"><div class="panel-head"><div><h2>Categorias de serviços</h2><p>Organize as especialidades da nossa Serra.</p></div><button class="btn primary small" data-action="entity-new" data-entity="categories">${icon('plus',15)} Nova categoria</button></div><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Serviços vinculados</th><th>Ações</th></tr></thead><tbody>${state.manage.categories.map(c=>`<tr><td>${icon(c.icon,16)} <strong>${esc(c.name)}</strong></td><td>${state.manage.services.filter(s=>s.category_id===c.id).length}</td><td>${rowActions('categories',c.id)}</td></tr>`).join('')}</tbody></table></div></div>`}
function reportRows(){const f=state.report;return state.manage.requests.filter(r=>(!f.status||r.status===f.status)&&(!f.from||r.created_at.slice(0,10)>=f.from)&&(!f.to||r.created_at.slice(0,10)<=f.to))}
function reportTable(){const rr=reportRows();return `<div class="result-count" style="padding:17px 22px;margin:0">${rr.length} registros no relatório · data de cadastro da solicitação</div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente / profissional</th><th>Data desejada</th><th>Status</th><th>Referência</th></tr></thead><tbody>${rr.map(r=>`<tr><td><strong>#${r.id} ${esc(r.title)}</strong><small>${esc(r.neighborhood)}</small></td><td>${esc(r.client_name)}<small>${esc(r.professional_name)}</small></td><td>${date(r.preferred_date)}</td><td><span class="badge ${r.status}">${statusLabel[r.status]}</span></td><td>${money(r.price)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum registro com os filtros selecionados.</td></tr>'}</tbody></table></div>`}
function reportsPanel(){const f=state.report;return `<div class="panel"><div class="panel-head"><div><h2>Relatório de solicitações</h2><p>Os arquivos exportados respeitam os filtros selecionados.</p></div><div class="export-actions"><button class="btn outline small" data-action="export" data-format="csv">${icon('download',14)} Exportar CSV</button><button class="btn primary small" data-action="export" data-format="pdf">${icon('download',14)} Exportar PDF</button></div></div><form class="report-filters" id="report-filters"><label>Status<select name="status"><option value="">Todos os status</option>${Object.entries(statusLabel).map(([v,l])=>`<option value="${v}" ${f.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Cadastradas a partir de<input type="date" name="from" value="${f.from}"></label><label>Cadastradas até<input type="date" name="to" value="${f.to}"></label></form><div id="report-results">${reportTable()}</div></div>`}
async function dashboard(){if(!state.user)return gated('Um espaço para fazer acontecer.','Entre no perfil profissional ou administrador para continuar.');if(state.user.role==='cliente')return gated('Seu espaço está nas conexões.','Acompanhe seus pedidos na área de solicitações.');state.manage=await api('/api/manage');const m=state.manage,admin=state.user.role==='admin';if(!admin&&!['servicos','pedidos'].includes(state.adminTab))state.adminTab='servicos';if(admin&&!['usuarios','servicos','categorias','relatorios'].includes(state.adminTab))state.adminTab='usuarios';return `<div class="container page"><div class="page-head"><div><div class="eyebrow"><span class="dot"></span> ${admin?'GESTÃO CONECTTA':'ÁREA DO PROFISSIONAL'}</div><h1>${admin?'Tudo conectado, por aqui.':'Seu talento em movimento.'}</h1><p>${admin?'Uma visão clara das pessoas, serviços e conexões da plataforma.':'Olá, '+esc(state.user.name.split(' ')[0])+'! Cuide do seu perfil, serviços e novos pedidos.'}</p></div><button class="btn outline" data-action="login">${icon('users',15)} Trocar perfil</button></div><div class="stats">${stat(admin?'Usuários':'Serviços',admin?m.users.length:m.services.length,admin?'clientes, profissionais e gestão':'no seu catálogo',admin?'users':'tools')}${stat(admin?'Serviços':'Pendentes',admin?m.services.length:m.requests.filter(r=>r.status==='pendente').length,admin?'no catálogo da plataforma':'aguardando sua resposta',admin?'tools':'clock')}${stat('Solicitações',m.requests.length,'conexões registradas','chat')}${stat('Concluídas',m.requests.filter(r=>r.status==='concluida').length,'serviços que viraram solução','check')}</div>${!admin?`<div class="profile-summary"><span class="avatar large">${esc(initials(state.user.name))}</span><div><h2>${esc(state.user.name)}</h2><p>${esc(m.professional?.profession||'Profissional')} · ${esc(state.user.neighborhood)}</p><p>${esc(m.professional?.bio||'')}</p></div><button class="btn outline small" data-action="edit-profile">${icon('edit',14)} Editar perfil</button></div>`:''}<div class="tabs">${(admin?[['usuarios','Usuários'],['servicos','Serviços'],['categorias','Categorias'],['relatorios','Relatórios']]:[['servicos','Meus serviços'],['pedidos','Pedidos recebidos']]).map(([v,l])=>`<button class="tab ${state.adminTab===v?'active':''}" data-action="admin-tab" data-id="${v}">${l}</button>`).join('')}</div>${{usuarios:usersPanel,servicos:servicePanel,categorias:categoryPanel,relatorios:reportsPanel,pedidos:()=>`<div class="requests-list">${m.requests.map(requestCard).join('')||empty('Seu próximo cliente vem aí.','Compartilhe seu perfil e mantenha seus serviços atualizados.')}</div>`}[state.adminTab]?.()||servicePanel()}</div>`}
function about(){return `<div class="container page"><div class="page-head"><div><div class="eyebrow"><span class="dot"></span> PYTHON + FLASK + SQLITE</div><h1>Conectta Serra, por dentro.</h1><p>Plataforma de serviços de Serra Talhada para demonstração no curso.</p></div></div><div class="notice">${icon('info',17)}<span>Os perfis de exemplo são fictícios. Cadastros, serviços, solicitações e mensagens são armazenados no banco SQLite do projeto.</span></div><div class="cards"><div class="service-option"><h3>Usuário / cliente</h3><p>Cadastro próprio, busca, favoritos, solicitações, mensagens e avaliações.</p></div><div class="service-option"><h3>Profissional</h3><p>Cadastro separado com profissão, perfil e gestão de serviços e pedidos.</p></div><div class="service-option"><h3>Administrador</h3><p>Gestão de usuários, categorias, serviços e relatórios PDF e CSV.</p></div></div><div class="panel" style="padding:25px;margin-top:20px"><h2 style="font-size:24px">Como apresentar</h2><p style="font-size:13px;color:#000;margin:14px 0">Use as páginas “Cadastro de usuário” e “Cadastro de profissional” para criar cada perfil. Em “Experimentar os perfis”, alterne entre os exemplos de cliente, profissional e administrador para demonstrar pedidos, conversa e relatórios.</p><p class="subdued">Backend em Python, Flask, SQLAlchemy e SQLite. Interface em HTML, CSS e JavaScript. Contas demonstrativas, sem login comercial com senhas.</p></div></div>`}
function route(){return (location.hash.slice(1)||'inicio').split('?')[0]}
let renderId=0;
async function render(){const id=++renderId;header();footer();const r=route();try{let html=r==='explorar'?catalog():r==='favoritos'?catalog(true):r==='solicitacoes'?requestsPage():r==='painel'?await dashboard():r==='cadastro-usuario'?registrationPage(false):r==='cadastro-profissional'?registrationPage(true):r==='projeto'?about():home();if(id!==renderId)return;$('#main').innerHTML=html;if(r==='como-funciona')setTimeout(()=>$('#como-funciona')?.scrollIntoView(),50)}catch(e){$('#main').innerHTML=`<div class="container error-page"><h1>Essa conexão falhou.</h1><p>${esc(e.message)}</p><button class="btn primary" data-action="reload">Tentar novamente</button></div>`}}
function login(){openModal(state.user?'Troque de perspectiva.':'Vamos fazer uma conexão?',state.user?'Experimente os três lados da plataforma.':'Escolha um perfil da demonstração para explorar.',`<div class="notice">${icon('info',16)}<span>Demonstração em Python/Flask. Os exemplos são fictícios. Novos registros ficam salvos no banco SQLite deste projeto.</span></div><div class="persona-options">${[['cliente','user','Sou cliente','Encontre profissionais, peça um orçamento e avalie.'],['profissional','tools','Sou profissional','Gerencie seus serviços e responda aos pedidos.'],['admin','shield','Sou administrador','Gerencie cadastros e exporte os relatórios.']].map(([v,ic,title,desc])=>`<button class="persona" data-action="persona" data-role="${v}"><span>${icon(ic,23)}</span><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow',18)}</button>`).join('')}</div><div class="login-bottom">Crie seu cadastro na área correspondente:<div class="login-signups"><button data-action="register">${icon('user',15)} Cadastro de usuário</button><button data-action="register-pro">${icon('tools',15)} Cadastro de profissional</button></div>${state.user?'<br><button data-action="logout" style="margin-top:15px;color:var(--muted)">Sair da demonstração</button>':''}</div>`)}
function register(pro=false){if($('#modal').open)$('#modal').close();const destination=pro?'cadastro-profissional':'cadastro-usuario';if(route()===destination)render();else location.hash=destination;window.scrollTo(0,0)}
function registrationPage(pro=false){
 const profile=pro?'profissional':'cliente';
 const title=pro?'Cadastro de profissional':'Cadastro de usuário';
 const benefits=pro?['Mostre seus serviços para Serra Talhada.','Receba solicitações e converse com clientes.','Gerencie seu catálogo e suas avaliações.']:['Encontre profissionais da nossa cidade.','Peça orçamentos e acompanhe seus pedidos.','Salve favoritos e avalie serviços concluídos.'];
 return `<div class="container page signup-page"><div class="breadcrumb"><a href="#inicio">Início</a> / ${title}</div><nav class="registration-switch" aria-label="Áreas de cadastro"><a href="#cadastro-usuario" class="${!pro?'active':''}" ${!pro?'aria-current="page"':''}>${icon('user',17)} Usuário / cliente</a><a href="#cadastro-profissional" class="${pro?'active':''}" ${pro?'aria-current="page"':''}>${icon('tools',17)} Profissional</a></nav><div class="signup-layout"><section class="signup-aside ${pro?'for-professionals':''}"><span class="signup-icon">${icon(pro?'tools':'user',32)}</span><div class="eyebrow"><span class="dot"></span> ${pro?'PARA QUEM OFERECE SERVIÇOS':'PARA QUEM PRECISA DE SERVIÇOS'}</div><h1>${pro?'Seu talento merece uma conexão.':'Encontre quem resolve perto de você.'}</h1><p>${pro?'Crie seu perfil profissional e apresente o que você faz bem.':'Crie sua conta de cliente para conectar suas necessidades aos talentos da nossa Serra.'}</p><ul>${benefits.map(item=>`<li>${icon('check',16)}<span>${item}</span></li>`).join('')}</ul><span class="signup-local">${icon('pin',15)} Feito para Serra Talhada, Pernambuco.</span></section><section class="signup-card" aria-labelledby="signup-title"><span class="badge ${profile}">${pro?'Prestador de serviços':'Conta de cliente'}</span><h2 id="signup-title">${title}</h2><p class="signup-intro">${pro?'Cadastre seus dados e informe sua profissão.':'Preencha seus dados para começar suas conexões.'}</p><form id="register-form" data-profile="${profile}">${errorBox()}<input type="hidden" name="role" value="${profile}"><p class="subdued signup-required">* Campos obrigatórios. O telefone é opcional.</p><div class="form-grid">${field('Nome completo *','name','','text',true,'minlength="3" maxlength="80" autocomplete="name"')}${field('E-mail *','email','','email',true,'maxlength="120" autocomplete="email"')}${field('Bairro em Serra Talhada *','neighborhood','','text',false,'minlength="2" maxlength="60" autocomplete="address-level3"')}${field('Telefone (opcional)','phone','','tel',false,'maxlength="30" autocomplete="tel"').replace(' required','')}${pro?field('Sua profissão *','profession','','text',true,'minlength="3" maxlength="80" placeholder="Ex.: eletricista residencial" autocomplete="organization-title"'):''}</div><div class="signup-form-actions"><button class="btn primary full" type="submit">${pro?'Criar perfil profissional':'Criar conta de usuário'} ${icon('arrow',16)}</button></div><p class="signup-storage">Demonstração acadêmica. Os dados ficam salvos no banco SQLite deste projeto, no seu computador.</p></form><p class="signup-other">${pro?'Quer contratar um serviço?':'Você oferece serviços?'} <a href="${pro?'#cadastro-usuario':'#cadastro-profissional'}">${pro?'Cadastre-se como usuário':'Cadastre-se como profissional'}</a></p><button class="text-btn signup-demo" data-action="login">Experimentar um perfil de demonstração ${icon('arrowup',14)}</button></section></div></div>`
}
async function profile(id){const d=await api('/api/professionals/'+id),p=d.professional;openModal('Conheça quem faz.','Perfil ilustrativo de demonstração · Serra Talhada, PE',`<div class="profile-top"><span class="avatar large">${esc(initials(p.name))}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.profession)}</p>${d.services[0]?rating(d.services[0]):''}</div></div><div class="profile-description">${esc(p.bio)}</div><div class="profile-facts"><span>${icon('pin',15)} ${esc(p.neighborhood)}, Serra Talhada</span><span>${icon('briefcase',15)} ${p.experience} anos de experiência (exemplo)</span></div><h3 class="modal-section-title">Serviços e orçamentos</h3>${d.services.map(s=>`<div class="service-option"><h4>${esc(s.title)}</h4><p>${esc(s.description)}</p><div class="price-row"><strong>${money(s.price)} <small>/ ${esc(s.unit)}</small></strong><button class="btn primary small" data-action="request" data-id="${s.id}">Pedir orçamento ${icon('arrow',14)}</button></div></div>`).join('')}<p class="subdued">Valores de referência. Preço final e disponibilidade são combinados na conversa. Não há pagamento pela plataforma.</p><h3 class="modal-section-title">Avaliações da comunidade</h3>${d.reviews.map(r=>`<div class="review"><div><strong>${esc(r.name)}</strong><span class="stars" aria-label="${r.rating} de 5 estrelas">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p>${esc(r.comment)}</p><small>${date(r.created_at)} · serviço concluído · exemplo</small></div>`).join('')||'<p class="subdued">Ainda não há avaliações. Cada conexão conta.</p>'}`)}
function requestForm(id){if(!state.user){login();return}if(state.user.role!=='cliente'){toast('Troque para o perfil cliente para pedir um orçamento.',true);login();return}const s=state.services.find(x=>x.id===Number(id));if(!s)return;openModal('Conte o que você precisa.','O profissional receberá sua solicitação de orçamento.',`<div class="selected-service"><strong>${esc(s.title)}</strong><span>${esc(s.name)} · a partir de ${money(s.price)} / ${esc(s.unit)}</span></div><form id="request-form" data-id="${s.id}">${errorBox()}<div class="form-grid">${area('Descreva o serviço','description','',10)}${field('Bairro do atendimento','neighborhood',state.user.neighborhood,'text',false,'maxlength="60"')}${field('Data desejada','preferred_date','','date',false,`min="${new Date().toISOString().slice(0,10)}"`)}</div><p class="subdued" style="margin-top:17px">A solicitação não confirma agendamento nem preço. Combine os detalhes na conversa.</p>${actions('Enviar solicitação')}</form>`)}
async function chat(id){const r=state.requests.find(x=>x.id===Number(id));if(!r)return;const msgs=await api(`/api/requests/${id}/messages`);openModal('Conversa e detalhes · #'+id,r.title,`<span class="badge ${r.status}" style="margin-bottom:15px">${statusLabel[r.status]}</span><div class="detail-box"><p>${esc(r.description)}</p><div class="detail-meta"><span>${icon('calendar',13)} ${date(r.preferred_date)}</span><span>${icon('pin',13)} ${esc(r.neighborhood)}</span><span>Referência: ${money(r.price)}</span></div></div><h3 class="modal-section-title">Converse por aqui</h3><p class="subdued">As mensagens ficam salvas neste pedido. Troque de perfil para responder pelo outro lado.</p><div class="chat-area" id="chat-area">${msgs.map(m=>`<div class="message ${m.sender_id===state.user.id?'mine':''}"><small>${esc(m.sender_name)} · ${date(m.created_at)}</small><p>${esc(m.body)}</p></div>`).join('')||'<p class="subdued">Comece essa conversa combinando os detalhes.</p>'}</div><form id="chat-form" class="chat-form" data-id="${id}"><input name="body" placeholder="Escreva sua mensagem…" aria-label="Sua mensagem" maxlength="2000" required><button class="btn primary" type="submit">Enviar ${icon('arrow',16)}</button></form>`);$('#chat-area').scrollTop=$('#chat-area').scrollHeight}
function reviewForm(id){openModal('Como foi essa conexão?','Sua avaliação ajuda a comunidade a encontrar bons profissionais.',`<form id="review-form" data-id="${id}">${errorBox()}<label class="field">Sua nota</label><div class="rating-select">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" ${n===5?'checked':''} required aria-label="${n} estrelas">${n}★</label>`).join('')}</div>${area('Conte sua experiência','comment','',5)}${actions('Publicar avaliação')}</form>`)}
const entityNames={users:'usuário',services:'serviço',categories:'categoria'};
function entityForm(entity,id){const r=id?state.manage[entity].find(x=>x.id===Number(id)):{};if(!r)return;let fields='';if(entity==='users')fields='<p class="subdued field full">* Campos obrigatórios. O telefone é opcional.</p>'+field('Nome completo *','name',r.name,'text',true,'minlength="3" maxlength="80"')+field('E-mail *','email',r.email,'email',true,'maxlength="120"')+field('Bairro *','neighborhood',r.neighborhood||'Centro','text',false,'maxlength="60"')+field('Telefone (opcional)','phone',r.phone,'tel',false,'maxlength="30"').replace(' required','');if(entity==='categories')fields=field('Nome da categoria','name',r.name,'text',true,'minlength="2" maxlength="60"');if(entity==='services'){fields=field('Título do serviço','title',r.title,'text',true,'minlength="3" maxlength="100"')+area('Descrição','description',r.description)+selectField('Categoria','category_id',state.categories.map(c=>[c.id,c.name]),r.category_id)+field('Preço inicial (R$)','price',r.price??'','number',false,'min="0" step="0.01" max="1000000"')+field('Unidade','unit',r.unit||'serviço','text',false,'maxlength="30"');if(state.user.role==='admin'&&!id){const pros=[...new Map(state.services.map(s=>[s.professional_id,[s.professional_id,s.name]])).values()];fields+=selectField('Profissional','professional_id',pros)}if(id)fields+=selectField('Situação','active',[['1','Ativo'],['0','Pausado']],r.active?'1':'0')};openModal((id?'Editar ':'Novo ')+entityNames[entity],entity==='users'&&!id?'Novo cadastro de cliente. Profissionais usam a página “Cadastro de profissional”.':'Preencha os dados e mantenha suas conexões atualizadas.',`<form id="entity-form" data-entity="${entity}" data-id="${id||''}">${errorBox()}<div class="form-grid">${fields}</div>${actions(id?'Salvar alterações':'Cadastrar')}</form>`)}
function entityView(entity,id){const r=state.manage[entity].find(x=>x.id===Number(id));if(!r)return;if(entity==='services'){openModal(r.title,r.category,`<div class="detail-box"><p>${esc(r.description)}</p><div class="detail-meta"><span>${esc(r.name)}</span><span>${money(r.price)} / ${esc(r.unit)}</span><span>${r.active?'Ativo':'Pausado'}</span></div></div><div class="modal-actions"><button class="btn primary" data-action="entity-edit" data-entity="services" data-id="${id}">Editar serviço</button></div>`);return}if(entity==='users'){openModal(r.name,'Dados do usuário',`<div class="detail-box"><p>E-mail: ${esc(r.email)}<br>Bairro: ${esc(r.neighborhood)}<br>Telefone: ${esc(r.phone)||'Não informado'}<br>Perfil: ${esc(r.role)}<br>Cadastro: ${r.demo?'Exemplo de demonstração':'Criado na plataforma'}</p></div>`);return}openModal(r.name,'Categoria de serviços',`<div class="detail-box"><p>${state.manage.services.filter(s=>s.category_id===r.id).length} serviços vinculados a esta categoria.</p></div>`)}
function confirmDelete(entity,id){const r=state.manage[entity].find(x=>x.id===Number(id));openModal('Excluir '+entityNames[entity]+'?','Esta ação remove o cadastro do banco de dados do projeto.',`<p>Você está excluindo <strong>${esc(r?.name||r?.title)}</strong>. Registros com vínculos são preservados para manter o histórico.</p><form id="delete-form" data-id="${id}" data-entity="${entity}">${errorBox()}<div class="modal-actions"><button type="button" class="btn outline" data-action="close">Manter cadastro</button><button type="submit" class="btn danger">${icon('trash',15)} Confirmar exclusão</button></div></form>`)}
function confirmStatus(id,status){openModal(status==='cancelada'?'Cancelar esta solicitação?':status==='concluida'?'Serviço concluído?':'Aceitar esta solicitação?',status==='concluida'?'Confirme após a execução do serviço. Você poderá avaliar em seguida.':'A alteração ficará visível para o cliente e para o profissional.',`<form id="status-form" data-id="${id}" data-status="${status}">${errorBox()}<p class="subdued">Solicitação #${id} · ${status==='aceita'?'o pedido passará para “Em andamento”.':status==='concluida'?'o pedido passará para “Concluída”.':'o pedido passará para “Cancelada”.'}</p>${actions('Confirmar')}</form>`)}
async function mutate(path,method,b,message){await api(path,method,b);$('#modal').close();await sync();await render();toast(message)}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id,entity,status}=el.dataset;try{if(action==='close')$('#modal').close();else if(action==='menu'){const m=$('.mobile-nav');m.classList.toggle('open');el.setAttribute('aria-expanded',m.classList.contains('open'))}else if(action==='login')login();else if(action==='register')register();else if(action==='register-pro')register(true);else if(action==='persona'){el.disabled=true;await api('/api/session','POST',{role:el.dataset.role});$('#modal').close();await sync();if(el.dataset.role!=='cliente')location.hash='painel';else location.hash='explorar';await render();toast('Você entrou como '+el.dataset.role+'. Explore as conexões!')}else if(action==='logout'){await mutate('/api/logout','POST',{},'Você saiu da demonstração.');location.hash='inicio'}else if(action==='category'){state.filter={q:'',category:id,neighborhood:'',sort:''};location.hash='explorar';await render();window.scrollTo(0,0)}else if(action==='profile')await profile(id);else if(action==='request')requestForm(id);else if(action==='favorite'){if(!state.user){login();return}const saved=!state.favorites.includes(Number(id));await api('/api/favorites','POST',{professional_id:Number(id),saved});await sync();await render();toast(saved?'Profissional salvo nos favoritos.':'Profissional removido dos favoritos.')}else if(action==='clear-filters'){state.filter={q:'',category:'',neighborhood:'',sort:''};await render()}else if(action==='request-tab'){state.requestFilter=id;await render()}else if(action==='admin-tab'){state.adminTab=id;await render()}else if(action==='chat')await chat(id);else if(action==='status')confirmStatus(id,status);else if(action==='review')reviewForm(id);else if(action==='entity-new')entityForm(entity);else if(action==='entity-edit')entityForm(entity,id);else if(action==='entity-view')entityView(entity,id);else if(action==='entity-delete')confirmDelete(entity,id);else if(action==='edit-profile'){const p=state.manage.professional;openModal('Seu perfil, sua história.','Conte o que você faz e como pode ajudar a nossa comunidade.',`<form id="profile-form">${errorBox()}<div class="form-grid">${field('Profissão','profession',p.profession,'text',true,'minlength="3" maxlength="80"')}${area('Sobre seu trabalho','bio',p.bio)}${field('Anos de experiência','experience',p.experience,'number',true,'min="0" max="60"')}</div>${actions('Salvar perfil')}</form>`)}else if(action==='export'){const f=state.report;if(f.from&&f.to&&f.from>f.to){toast('A data inicial deve ser anterior à data final.',true);return}const params=new URLSearchParams({...state.report,format:el.dataset.format});const r=await fetch('/api/reports?'+params);if(!r.ok){const err=await r.json();throw Error(err.error)}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='conectta-relatorio.'+el.dataset.format;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Relatório '+el.dataset.format.toUpperCase()+' exportado com os filtros selecionados.')}else if(action==='reload'){await sync();await render()}}catch(err){toast(err.message,true);el.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();const b=Object.fromEntries(new FormData(f)),btn=f.querySelector('button[type="submit"]');if(f.id==='hero-search'){state.filter={q:b.q,category:'',neighborhood:'',sort:''};location.hash='explorar';await render();window.scrollTo(0,0);return}if(['filters','report-filters'].includes(f.id))return;if(btn)btn.disabled=true;const err=$('.form-error',f);if(err)err.classList.remove('show');try{if(f.id==='register-form'){const endpoint=f.dataset.profile==='profissional'?'/api/register/professionals':'/api/register/users';await mutate(endpoint,'POST',b,f.dataset.profile==='profissional'?'Perfil profissional criado. Cadastre seu primeiro serviço!':'Sua conta de usuário foi criada. Vamos conectar!');location.hash=state.user.role==='profissional'?'painel':'explorar'}else if(f.id==='request-form'){b.service_id=Number(f.dataset.id);await mutate('/api/requests','POST',b,'Solicitação enviada! Combine os detalhes na conversa.');state.requestFilter='todas';location.hash='solicitacoes';await render()}else if(f.id==='review-form'){b.request_id=Number(f.dataset.id);b.rating=Number(b.rating);await mutate('/api/reviews','POST',b,'Avaliação registrada. Obrigado por compartilhar!')}else if(f.id==='chat-form'){await api(`/api/requests/${f.dataset.id}/messages`,'POST',b);await chat(f.dataset.id);$('#chat-form input').focus()}else if(f.id==='entity-form'){const entity=f.dataset.entity,id=f.dataset.id;if(entity==='services'){b.price=Number(b.price);b.category_id=Number(b.category_id);if(b.active!==undefined)b.active=b.active==='1'}await mutate(`/api/${entity}${id?'/'+id:''}`,id?'PUT':'POST',b,id?'Alterações salvas.':'Cadastro realizado.')}else if(f.id==='delete-form')await mutate(`/api/${f.dataset.entity}/${f.dataset.id}`,'DELETE',{},'Cadastro excluído.');else if(f.id==='status-form')await mutate('/api/requests/'+f.dataset.id,'PATCH',{status:f.dataset.status},'Status da solicitação atualizado.');else if(f.id==='profile-form')await mutate('/api/profile','PUT',b,'Perfil atualizado.')}catch(error){if(err){err.textContent=error.message;err.classList.add('show')}else toast(error.message,true)}finally{if(btn)btn.disabled=false}});
let filterTimer;document.addEventListener('input',e=>{if(e.target.closest('#filters')){clearTimeout(filterTimer);filterTimer=setTimeout(()=>{const f=$('#filters');if(!f)return;state.filter=Object.fromEntries(new FormData(f));const pos=e.target.selectionStart;const name=e.target.name;const ss=filteredServices(route()==='favoritos');$('#catalog-cards').innerHTML=ss.map(card).join('')||empty('Não encontramos essa conexão.','Tente outro serviço, profissional ou categoria.');$('.result-count>span').innerHTML=`<strong>${ss.length}</strong> serviços encontrados · perfis de demonstração`;},160)}if(e.target.id==='table-search'){usersFilters.q=e.target.value;updateUsersResults()}});
document.addEventListener('change',e=>{if(e.target.id==='users-role-filter'){usersFilters.role=e.target.value;updateUsersResults()}if(e.target.closest('#filters')){state.filter=Object.fromEntries(new FormData($('#filters')));const ss=filteredServices(route()==='favoritos');$('#catalog-cards').innerHTML=ss.map(card).join('')||empty('Não encontramos essa conexão.','Tente outro filtro para encontrar um profissional.');$('.result-count>span').innerHTML=`<strong>${ss.length}</strong> serviços encontrados · perfis de demonstração`;}if(e.target.closest('#report-filters')){state.report=Object.fromEntries(new FormData($('#report-filters')));$('#report-results').innerHTML=reportTable()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('hashchange',()=>{render();if(route()!=='como-funciona')window.scrollTo(0,0)});
(async()=>{try{await sync();await render()}catch(e){$('#main').innerHTML=`<div class="container error-page"><h1>Vamos tentar essa conexão de novo?</h1><p>${esc(e.message)}</p><button class="btn primary" data-action="reload">Tentar novamente</button></div>`}})();

